  stackSize?: number;
  /** Drag distance (px) required to commit a swipe. */
  threshold?: number;
}

interface ThrowVector {
  direction: SwipeDirection;
  vx: number;
  vy: number;
}

interface DeckCardProps {
  disabled: boolean;
  isFront: boolean;
  item: CardSwipeDeckItem;
  labels: Required<CardSwipeDeckLabels>;
  onCommit: (direction: SwipeDirection, info?: PanInfo) => void;
  onExitComplete: () => void;
  pos: number;
  rotationFactor: number;
  shouldReduceMotion: boolean;
  stackOffset: number;
  stackSize: number;
  threshold: number;
  throwVector: ThrowVector | null;
  zIndex: number;
}

const DeckCard = ({
  disabled,
  isFront,
  item,
  labels,
  onCommit,
  onExitComplete,
  pos,
  rotationFactor,
  shouldReduceMotion,
  stackOffset,
  stackSize,
  threshold,
  throwVector,
  zIndex,
}: DeckCardProps) => {
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const isExiting = throwVector !== null;

  const rotate = useTransform(
    x,
    [-DRAG_RANGE, DRAG_RANGE],
    [-rotationFactor, rotationFactor]
  );

  const stampSpan = threshold * STAMP_RATIO;
  const washSpan = threshold * WASH_RATIO;

  // Stamps and wash are driven straight off the drag distance, so they bloom
  // continuously under the finger instead of snapping in at the threshold.
  const likeOpacity = useTransform(x, [0, stampSpan], [0, 1]);
  const likeScale = useTransform(x, [0, stampSpan], [STAMP_MIN_SCALE, 1]);
  const nopeOpacity = useTransform(x, [-stampSpan, 0], [1, 0]);
  const nopeScale = useTransform(x, [-stampSpan, 0], [1, STAMP_MIN_SCALE]);
  const likeWash = useTransform(x, [0, washSpan], [0, WASH_MAX_OPACITY]);
  const nopeWash = useTransform(x, [-washSpan, 0], [WASH_MAX_OPACITY, 0]);

  useEffect(() => {
    if (!throwVector || shouldReduceMotion) {
      return;
    }
    const targetX =
      throwVector.direction === "left" ? -EXIT_DISTANCE : EXIT_DISTANCE;
    const speed = Math.max(Math.abs(throwVector.vx), MIN_THROW_SPEED);
    const signedVx = throwVector.direction === "left" ? -speed : speed;
    // Keep the throw on the trajectory the finger was already describing.
    const targetY = y.get() + throwVector.vy * THROW_DURATION;

    const xControls = animate(x, targetX, {
      ...THROW_TRANSITION,
      velocity: signedVx,
    });
    const yControls = animate(y, targetY, {
      ...THROW_TRANSITION,
      velocity: throwVector.vy,
    });

    return () => {
      xControls.stop();
      yControls.stop();
    };
  }, [throwVector, shouldReduceMotion, x, y]);

  const handleDragEnd = useCallback(
    (_event: unknown, info: PanInfo) => {
      if (disabled) {
        return;
      }
      const shouldCommit =
        Math.abs(info.offset.x) > threshold ||
        Math.abs(info.velocity.x) > VELOCITY_COMMIT_THRESHOLD;

      if (shouldCommit) {
        onCommit(info.offset.x > 0 ? "right" : "left", info);
        return;
      }
      // Below threshold: elastic snap back to centre.
      animate(x, 0, SNAP_BACK_TRANSITION);
      animate(y, 0, SNAP_BACK_TRANSITION);
    },
    [disabled, onCommit, threshold, x, y]
  );

  const isBuried = pos >= stackSize;
  const canDrag = isFront && !disabled && !isExiting;

  return (
    <motion.div
      animate={{
        scale: 1 - pos * STACK_SCALE_STEP,
        y: pos * stackOffset,
      }}
      className="absolute inset-0"
      initial={false}
      style={{ zIndex }}
      transition={shouldReduceMotion ? { duration: 0 } : STACK_TRANSITION}
    >
      <motion.div
        animate={
          isExiting
            ? {
                opacity: 0,
                transition: shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      delay: FADE_DELAY,
                      duration: FADE_DURATION,
                      ease: FADE_EASE,
                    },
              }
            : { opacity: isBuried ? 0 : 1 }
        }
        className="relative h-full w-full cursor-grab overflow-hidden rounded-[28px] bg-background shadow-[0_1px_2px_rgba(0,0,0,0.06),0_10px_20px_-8px_rgba(0,0,0,0.18),0_28px_56px_-20px_rgba(0,0,0,0.32)] ring-1 ring-foreground/10 active:cursor-grabbing"
        drag={canDrag}
        initial={false}
        dragConstraints={{ bottom: VERTICAL_LIMIT, top: -VERTICAL_LIMIT }}
        dragElastic={{ bottom: 0.35, left: 1, right: 1, top: 0.35 }}
        dragMomentum={false}
        onAnimationComplete={() => {
          if (isExiting) {
            onExitComplete();
          }
        }}
        onDragEnd={handleDragEnd}
        style={{
          rotate,
          transformOrigin: PIVOT_ORIGIN,
          x,
          y,
        }}
        transition={shouldReduceMotion ? { duration: 0 } : STACK_TRANSITION}
        whileDrag={shouldReduceMotion ? undefined : { scale: 1.02 }}
      >
        {item.content}

        {/* Kept mounted through the throw so the stamp flies off with the card. */}
        {isFront ? (
          <>
            {/* Colour wash — the card itself tints toward the outcome. */}
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 bg-gradient-to-l from-green/55 via-green/15 to-transparent"
              style={{ opacity: likeWash }}
            />
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 bg-gradient-to-r from-destructive/55 via-destructive/15 to-transparent"
              style={{ opacity: nopeWash }}
            />

            {/* Stamps — outlined, rotated, driven by drag distance. */}
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute top-7 left-6 rounded-xl border-[3px] border-green px-3 py-1 font-black text-2xl text-green uppercase leading-none tracking-[0.08em] drop-shadow-sm"
              style={{
                opacity: likeOpacity,
                rotate: -20,
                scale: likeScale,
              }}
            >
              {labels.right}
            </motion.div>
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute top-7 right-6 rounded-xl border-[3px] border-destructive px-3 py-1 font-black text-2xl text-destructive uppercase leading-none tracking-[0.08em] drop-shadow-sm"
              style={{
                opacity: nopeOpacity,
                rotate: 20,
                scale: nopeScale,
              }}
            >
              {labels.left}
            </motion.div>
          </>
        ) : null}
      </motion.div>
    </motion.div>
  );
};

export function CardSwipeDeck({
  className,
  disabled = false,
  items,
  labels,
  onEmpty,
  onSwipe,
  ref,
  rotationFactor = DEFAULT_ROTATION_FACTOR,
  stackOffset = DEFAULT_STACK_OFFSET,
  stackSize = DEFAULT_STACK_SIZE,
  threshold = DEFAULT_THRESHOLD,
}: CardSwipeDeckProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const instant = Boolean(shouldReduceMotion) || !motionOn;
  const [removedIds, setRemovedIds] = useState<Set<string>>(new Set());
  const [exiting, setExiting] = useState<{
    id: string;
    vector: ThrowVector;
  } | null>(null);

  const remaining = items.filter((item) => !removedIds.has(item.id));
  // One extra card is mounted so the stack keeps its depth while the top
  // card is flying away.
  const visible = remaining.slice(0, stackSize + 1);

  const commitSwipe = (direction: SwipeDirection, info?: PanInfo) => {
    if (disabled || exiting) {
      return;
    }
    const [top] = remaining;
    if (!top) {
      return;
    }
    onSwipe?.(top.id, direction);
    const wasLast = remaining.length === 1;

    if (instant) {
      setRemovedIds((prev) => new Set(prev).add(top.id));
    } else {
      setExiting({
        id: top.id,
        vector: {
          direction,
          vx: info?.velocity.x ?? 0,
          vy: info?.velocity.y ?? DEFAULT_THROW_LIFT,
        },
      });
    }
    if (wasLast) {
      onEmpty?.();
    }
  };

  const handleExitComplete = useCallback((id: string) => {
    setRemovedIds((prev) => new Set(prev).add(id));
    setExiting(null);
  }, []);

  const commitRef = useRef(commitSwipe);
  useEffect(() => {
    commitRef.current = commitSwipe;
  }, [commitSwipe]);

  useImperativeHandle(
    ref,
    () => ({
      reset: () => {
        setRemovedIds(new Set());
        setExiting(null);
      },
      swipeLeft: () => commitRef.current("left"),
      swipeRight: () => commitRef.current("right"),
    }),
    []
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) {
      return;
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      commitSwipe("left");
    } else if (event.key === "ArrowRight" || event.key === "Enter") {
      event.preventDefault();
      commitSwipe("right");
    }
  };

  const resolvedLabels: Required<CardSwipeDeckLabels> = {
    left: labels?.left ?? "Nope",
    right: labels?.right ?? "Like",
  };

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: Interactive swipeable widget requires event handlers
    <div
      aria-label="Swipeable card deck"
      className={cn(
        "relative h-[480px] w-[340px] max-w-full touch-pan-y outline-none",
        className
      )}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="card-swipe-deck"
      onKeyDown={handleKeyDown}
      ref={hostRef}
      role="application"
      // biome-ignore lint/a11y/noNoninteractiveTabindex: Required for keyboard navigation
      tabIndex={0}
    >
      {visible.length === 0 ? (
        <div className="flex h-full w-full items-center justify-center rounded-[28px] border border-foreground/10 border-dashed">
          <p className="text-center text-muted-foreground text-sm">
            No more cards
          </p>
        </div>
      ) : (
        visible.map((item, index) => {
          const isExitingCard = exiting?.id === item.id;
          // While the top card leaves, everything behind it slides forward
          // one slot — the next card scales up as the throw happens.
          const pos = exiting ? Math.max(index - 1, 0) : index;

          return (
            <DeckCard
              disabled={disabled}
              isFront={index === 0}
              item={item}
              key={item.id}
              labels={resolvedLabels}
              onCommit={commitSwipe}
              onExitComplete={() => handleExitComplete(item.id)}
              pos={isExitingCard ? 0 : pos}
              rotationFactor={rotationFactor}
              shouldReduceMotion={instant}
              stackOffset={stackOffset}
              stackSize={stackSize}
              threshold={threshold}
              throwVector={isExitingCard ? exiting.vector : null}
              zIndex={visible.length - index}
            />
          );
        })
      )}
      <div aria-live="polite" className="sr-only">
        {remaining.length > 0
          ? `${remaining.length} card${remaining.length === 1 ? "" : "s"} remaining`
          : "No cards remaining"}
      </div>
    </div>
  );
}

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"

import { CardTossStack } from "./card-toss-stack"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
})

afterEach(() => {
  cleanup()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function topCard() {
  return screen.getByRole("button", { name: /草案/ })
}

test("默认渲染三张卡片，不读减弱动效时没有 data-reduced", () => {
  render(<CardTossStack />)
  expect(screen.getByText("草案")).toBeInTheDocument()
  expect(screen.getByText("评审")).toBeInTheDocument()
  expect(screen.getByText("发布")).toBeInTheDocument()
  expect(document.querySelector("[data-slot='card-toss-stack']")).not.toHaveAttribute("data-reduced")
})

test("方向键把顶卡甩出，惯性走完后回调", () => {
  const onToss = vi.fn()
  render(<CardTossStack onToss={onToss} />)
  fireEvent.keyDown(topCard(), { key: "ArrowRight" })
  expect(onToss).not.toHaveBeenCalled()
  expect(document.querySelector("[data-flying='true']")).toBeTruthy()
  pump(24)
  expect(onToss).toHaveBeenCalledWith("draft")
  expect(screen.getByRole("button", { name: /评审/ })).toBeInTheDocument()
  expect(screen.queryByRole("button", { name: /草案/ })).toBeNull()
})

test("拖得不够远时卡片回到原处，不回调", () => {
  const onToss = vi.fn()
  render(<CardTossStack onToss={onToss} />)
  const card = topCard()
  fireEvent.pointerDown(card, { clientX: 0, clientY: 0, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerMove(card, { clientX: 10, clientY: 4, pointerId: 1, timeStamp: 80 })
  fireEvent.pointerUp(card, { clientX: 10, clientY: 4, pointerId: 1, timeStamp: 100 })
  pump(8)
  expect(onToss).not.toHaveBeenCalled()
  expect(screen.getByRole("button", { name: /草案/ })).toBeInTheDocument()
  expect(queue.size).toBe(0)
})

test("拖过阈值后沿出手方向飞走", () => {
  const onToss = vi.fn()
  render(<CardTossStack onToss={onToss} />)
  const card = topCard()
  fireEvent.pointerDown(card, { clientX: 20, clientY: 20, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerMove(card, { clientX: 160, clientY: 30, pointerId: 1, timeStamp: 30 })
  fireEvent.pointerUp(card, { clientX: 160, clientY: 30, pointerId: 1, timeStamp: 40 })
  expect(document.querySelector("[data-flying='true']")).toBeTruthy()
  pump(24)
  expect(onToss).toHaveBeenCalledWith("draft")
})

test("触屏拖拽同样可以甩出，不依赖悬停", () => {
  const onToss = vi.fn()
  render(<CardTossStack onToss={onToss} />)
  const card = topCard()
  fireEvent.pointerDown(card, { button: 0, clientX: 0, clientY: 0, pointerId: 2, pointerType: "touch", timeStamp: 0 })
  fireEvent.pointerUp(card, { button: 0, clientX: 140, clientY: 10, pointerId: 2, pointerType: "touch", timeStamp: 40 })
  pump(24)
  expect(onToss).toHaveBeenCalledWith("draft")
})

test("减弱动效时方向键立刻拿走顶卡，并且不申请动画帧", () => {
  reduceMotion = true
  const onToss = vi.fn()
  render(<CardTossStack onToss={onToss} />)
  expect(document.querySelector("[data-slot='card-toss-stack']")).toHaveAttribute("data-reduced", "true")
  fireEvent.keyDown(topCard(), { key: "ArrowRight" })
  expect(onToss).toHaveBeenCalledWith("draft")
  expect(document.querySelector("[data-flying='true']")).toBeNull()
  expect(queue.size).toBe(0)
})

"use client"

import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface TossCard {
  id: string
  title: string
  detail: string
}

export interface CardTossStackProps {
  cards?: readonly TossCard[]
  onToss?: (id: string) => void
  color?: string
  size?: number
  duration?: number
  fling?: number
  className?: string
}

const DEFAULT_CARDS: readonly TossCard[] = [
  { id: "draft", title: "草案", detail: "先把范围写清楚" },
  { id: "review", title: "评审", detail: "找一个人看一眼" },
  { id: "ship", title: "发布", detail: "合进去再看效果" },
]

interface Origin {
  x: number
  y: number
  t: number
}

interface Flight {
  id: string
  x: number
  y: number
  vx: number
  vy: number
}

function CardTossStack({
  cards = DEFAULT_CARDS,
  onToss,
  color,
  size = 280,
  duration = 700,
  fling = 0.8,
  className,
}: CardTossStackProps) {
  const reduced = usePrefersReducedMotion()
  const [pile, setPile] = useState<readonly TossCard[]>(cards)
  const [drag, setDrag] = useState({ x: 0, y: 0, active: false })
  const [pose, setPose] = useState({ x: 0, y: 0 })
  const [ghost, setGhost] = useState<TossCard | null>(null)
  const origin = useRef<Origin | null>(null)
  const flight = useRef<Flight | null>(null)
  const done = useRef(new Set<string>())
  const onTossRef = useRef(onToss)
  const reducedRef = useRef(reduced)
  const durationRef = useRef(duration)
  useEffect(() => {
    onTossRef.current = onToss
    reducedRef.current = reduced
    durationRef.current = duration
  })
  const accent = color ?? "var(--primary)"
  const top = pile[0]

  function finish(id: string) {
    if (done.current.has(id)) return
    done.current.add(id)
    flight.current = null
    setGhost(null)
    onTossRef.current?.(id)
  }

  useEffect(() => {
    const current = flight.current
    if (!current) return
    if (reduced) {
      finish(current.id)
      return
    }
    let x = current.x
    let y = current.y
    let vx = current.vx
    let vy = current.vy
    let last = 0
    let elapsed = 0
    let raf = 0
    const step = (now: number) => {
      if (reducedRef.current) {
        finish(current.id)
        return
      }
      const dt = last === 0 ? 16 : Math.min(32, Math.max(0, now - last))
      last = now
      elapsed += dt
      const keep = Math.exp(-dt / Math.max(120, durationRef.current))
      vx *= keep
      vy *= keep
      x += vx * dt
      y += vy * dt
      const stopped = Math.hypot(x, y) > 420 || elapsed >= durationRef.current || Math.hypot(vx, vy) < 0.05
      if (stopped) {
        finish(current.id)
        return
      }
      setPose({ x, y })
      raf = requestAnimationFrame(step)
    }
    raf = requestAnimationFrame(step)
    return () => cancelAnimationFrame(raf)
  }, [ghost, reduced])

  function launch(card: TossCard, x: number, y: number, vx: number, vy: number) {
    setPile((prev) => prev.filter((item) => item.id !== card.id))
    setDrag({ x: 0, y: 0, active: false })
    if (reduced) {
      finish(card.id)
      return
    }
    const speed = Math.hypot(vx, vy) || 1
    const boost = speed < 1 ? 1.2 / speed : 1
    flight.current = { id: card.id, x, y, vx: vx * boost, vy: vy * boost }
    setPose({ x, y })
    setGhost(card)
  }

  function onPointerDown(event: ReactPointerEvent<HTMLButtonElement>) {
    if (ghost || !top) return
    if (event.pointerType === "mouse" && event.button !== 0) return
    event.currentTarget.setPointerCapture?.(event.pointerId)
    origin.current = { x: event.clientX, y: event.clientY, t: event.timeStamp }
    setDrag({ x: 0, y: 0, active: true })
  }

  function onPointerMove(event: ReactPointerEvent<HTMLButtonElement>) {
    const start = origin.current
    if (!start) return
    setDrag({ x: event.clientX - start.x, y: event.clientY - start.y, active: true })
  }

  function onPointerUp(event: ReactPointerEvent<HTMLButtonElement>) {
    const start = origin.current
    origin.current = null
    if (!start || !top) return
    const dx = event.clientX - start.x
    const dy = event.clientY - start.y
    const dt = Math.max(16, event.timeStamp - start.t)
    const vx = dx / dt
    const vy = dy / dt
    if (Math.hypot(dx, dy) < 72 && Math.hypot(vx, vy) < fling) {
      setDrag({ x: 0, y: 0, active: false })
      return
    }
    launch(top, dx, dy, vx, vy)
  }

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (!top || ghost) return
    const vx = event.key === "ArrowLeft" ? -1.8 : event.key === "ArrowRight" ? 1.8 : 0
    const vy = event.key === "ArrowUp" ? -1.8 : event.key === "ArrowDown" ? 1.4 : 0
    if (vx === 0 && vy === 0) return
    event.preventDefault()
    launch(top, 0, 0, vx, vy)
  }

  return (
    <div
      className={cn("relative h-52", className)}
      data-reduced={reduced ? "true" : undefined}
      data-slot="card-toss-stack"
      style={{ width: size }}
    >
      {pile.length === 0 && ghost === null ? (
        <p className="text-muted-foreground absolute inset-0 grid place-items-center text-sm">没有卡片了</p>
      ) : null}
      {pile.slice(0, 3).map((card, index) => {
        const isTop = index === 0
        const x = isTop ? drag.x : 0
        const y = index * 10 + (isTop ? drag.y : 0)
        const style = {
          background: "var(--card)",
          borderColor: accent,
          color: "var(--card-foreground)",
          transform: `translate(${x}px, ${y}px) scale(${1 - index * 0.04})`,
          zIndex: 20 - index,
        }
        const face = (
          <>
            <span className="block text-base font-medium">{card.title}</span>
            <span className="text-muted-foreground mt-1 block text-sm">{card.detail}</span>
          </>
        )
        if (!isTop) {
          return (
            <div
              aria-hidden
              className="absolute inset-x-0 top-0 h-36 rounded-2xl border px-4 py-3 shadow-md"
              key={card.id}
              style={style}
            >
              {face}
            </div>
          )
        }
        return (
          <button
            className={cn(
              "absolute inset-x-0 top-0 h-36 touch-none rounded-2xl border px-4 py-3 text-left shadow-md select-none",
              "motion-reduce:transition-none",
              drag.active || reduced ? "transition-none" : "transition-transform duration-300",
            )}
            key={card.id}
            onKeyDown={onKeyDown}
            onPointerCancel={() => {
              origin.current = null
              setDrag({ x: 0, y: 0, active: false })
            }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            style={style}
            type="button"
          >
            {face}
          </button>
        )
      })}
      {ghost ? (
        <div
          className="pointer-events-none absolute inset-x-0 top-0 h-36 rounded-2xl border px-4 py-3 shadow-md motion-reduce:transition-none"
          data-flying="true"
          style={{
            background: "var(--card)",
            borderColor: accent,
            color: "var(--card-foreground)",
            transform: `translate(${pose.x}px, ${pose.y}px) rotate(${pose.x * 0.04}deg)`,
            zIndex: 30,
          }}
        >
          <span className="block text-base font-medium">{ghost.title}</span>
