  { id: "seat", type: "added", title: "选座键盘", body: "方向键可以走到已售座位并跳过。", date: "10-18" },
  { id: "wave", type: "improved", title: "海况滑杆", body: "风暴只加大浪高，不换一套画面。", date: "10-12" },
