// Ported from beUI (MIT, (c) 2026 Saurabh Chauhan) — https://github.com/starc007/ui-components/blob/main/components/motion/chromatic-text-reveal.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"
import { motion, type MotionStyle } from "motion/react"
import { useCallback, useEffect, useRef, useState } from "react"

const TRAIL = 14

const DEFAULT_COLORS = ["var(--primary)", "var(--ring)", "var(--accent)"]

export interface ChromaticTextRevealProps {
  prefix?: string
  words?: string[]
  colors?: string[]
  /** Settled text color. Defaults to the foreground token. */
  color?: string
  /** Sweep length, in milliseconds. */
  duration?: number
  /** Wait before the first sweep, in milliseconds. */
  delay?: number
  /** Rest between words, in milliseconds. */
  interval?: number
  loop?: boolean
  /** Type size, in pixels. */
  fontSize?: number
  startOnView?: boolean
  once?: boolean
  className?: string
}

function gradient(colors: string[], foreground: string) {
  const palette = colors.length > 0 ? colors : DEFAULT_COLORS
  const stops = palette.map((stop, index) => {
    const offset = palette.length === 1 ? 0 : -TRAIL + (index / (palette.length - 1)) * TRAIL * 2
    const operator = offset < 0 ? "-" : "+"
    const distance = Number(Math.abs(offset).toFixed(2))
    return `${stop} calc(var(--chromatic-sweep) ${operator} ${distance}%)`
  })
  return `linear-gradient(90deg, ${foreground} 0%, ${foreground} calc(var(--chromatic-sweep) - ${TRAIL}%), ${stops.join(", ")}, transparent calc(var(--chromatic-sweep) + ${TRAIL}%), transparent 100%)`
}

export function ChromaticTextReveal({
  prefix = "Motion that feels",
  words = ["natural.", "intentional.", "alive."],
  colors = DEFAULT_COLORS,
  color = "var(--foreground)",
  duration = 1200,
  delay = 0,
  interval = 800,
  loop = true,
  fontSize = 48,
  startOnView = true,
  once = true,
  className,
}: ChromaticTextRevealProps) {
  const ref = useRef<HTMLSpanElement>(null)
  const timerRef = useRef<number | null>(null)
  const prefersReduced = usePrefersReducedMotion()
  const live = useAnimationActive(ref)
  const [wordIndex, setWordIndex] = useState(0)
  const [seen, setSeen] = useState(false)
  const still = prefersReduced || !live
  const hasWords = words.length > 0
  const activeIndex = hasWords ? wordIndex % words.length : 0
  const activeWord = words[activeIndex] ?? ""
  const sizingWords = Array.from(new Set(words))
  const shouldReveal = !startOnView || seen || prefersReduced

  useEffect(() => {
    const node = ref.current
    if (!node || typeof IntersectionObserver === "undefined") return
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[entries.length - 1]
        if (!entry?.isIntersecting) {
          if (!once) setSeen(false)
          return
        }
        setSeen(true)
      },
      { threshold: 0.4 },
    )
    observer.observe(node)
    return () => observer.disconnect()
  }, [once])

  const clearPending = useCallback(() => {
    if (timerRef.current != null) {
      window.clearTimeout(timerRef.current)
      timerRef.current = null
    }
  }, [])

  useEffect(() => {
    clearPending()
    if (still || !shouldReveal || words.length < 2) return
    const isLast = activeIndex === words.length - 1
    if (isLast && !loop) return
    timerRef.current = window.setTimeout(() => {
      setWordIndex((index) => (index + 1) % words.length)
    }, interval)
    return clearPending
  }, [activeIndex, clearPending, interval, live, loop, shouldReveal, still, words.length])

  const start = `-${TRAIL}%`
  const finish = `${100 + TRAIL}%`

  return (
    <span
      ref={ref}
      data-reduced={prefersReduced ? "" : undefined}
      data-motion={live ? "on" : "off"}
      style={{ fontSize, color }}
      className={cn("inline-flex items-baseline motion-reduce:transition-none", className)}
    >
      <span className="whitespace-nowrap">
        {prefix}
        {hasWords ? "\u00A0" : null}
      </span>
      {hasWords ? (
        <span className="relative inline-grid">
          {sizingWords.map((word) => (
            <span key={word} aria-hidden className="invisible col-start-1 row-start-1 whitespace-nowrap">
              {word}
            </span>
          ))}
          <motion.span
            key={`${activeWord}-${activeIndex}`}
            aria-hidden
            initial={still ? false : { opacity: 0.56, filter: "blur(6px)", transform: "translateY(5px)" }}
            animate={{
              "--chromatic-sweep": shouldReveal ? finish : start,
              opacity: 1,
              filter: "blur(0px)",
              transform: "translateY(0px)",
            }}
            transition={{
              "--chromatic-sweep": still ? { duration: 0 } : { duration: duration / 1000, delay: delay / 1000, ease: [0.77, 0, 0.175, 1] },
              opacity: still ? { duration: 0 } : { duration: 0.28 },
              filter: still ? { duration: 0 } : { duration: 0.36 },
              transform: still ? { duration: 0 } : { duration: 0.36 },
            }}
            className="absolute start-0 top-0 whitespace-nowrap bg-clip-text text-transparent [background-image:var(--chromatic-gradient)] [contain:paint]"
            style={
              {
                "--chromatic-sweep": still || prefersReduced ? finish : start,
                "--chromatic-gradient": gradient(colors, color),
                backgroundSize: "100% 100%",
                backgroundRepeat: "no-repeat",
              } as MotionStyle
            }
          >
            {activeWord}
          </motion.span>
          <span className="sr-only">{activeWord}</span>
        </span>
      ) : null}
    </span>
  )
}

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface CinemaSeatPickerProps {
  className?: string
}

const ROWS = ["A", "B", "C", "D", "E"]
const COLS = 8
const PRICE = 48

function seatId(row: string, col: number) {
  return `${row}${col}`
}

function isTaken(rowIndex: number, col: number) {
  return (rowIndex * 3 + col) % 7 === 0
}

function CinemaSeatPicker({ className }: CinemaSeatPickerProps) {
  usePrefersReducedMotion()
  const [selected, setSelected] = React.useState<string[]>([])
  const [cursor, setCursor] = React.useState({ row: 0, col: 1 })
  const total = selected.length * PRICE

  const move = (dRow: number, dCol: number) => {
    setCursor((current) => ({
      row: Math.min(ROWS.length - 1, Math.max(0, current.row + dRow)),
      col: Math.min(COLS, Math.max(1, current.col + dCol)),
    }))
  }

  const toggle = (id: string, taken: boolean) => {
    if (taken) return
    setSelected((current) => (current.includes(id) ? current.filter((item) => item !== id) : [...current, id]))
  }

  return (
    <div data-slot="cinema-seat-picker" className={cn("grid w-full gap-4 md:grid-cols-[1fr_14rem]", className)}>
      <div
        role="grid"
        aria-label="选座。方向键移动，回车切换座位。"
        tabIndex={0}
        className="rounded-xl border p-4 outline-none focus-visible:ring-2 focus-visible:ring-primary"
        onKeyDown={(event) => {
          const keyMap: Record<string, [number, number]> = {
            ArrowUp: [-1, 0],
            ArrowDown: [1, 0],
            ArrowLeft: [0, -1],
            ArrowRight: [0, 1],
          }
          const step = keyMap[event.key]
          if (step) {
            event.preventDefault()
            move(step[0], step[1])
            return
          }
          if (event.key !== "Enter" && event.key !== " ") return
          event.preventDefault()
          const row = ROWS[cursor.row] ?? "A"
          const id = seatId(row, cursor.col || 1)
          toggle(id, isTaken(cursor.row, cursor.col || 1))
        }}
      >
        <div className="mb-4 rounded-md bg-muted py-2 text-center text-xs tracking-[0.3em]">银幕</div>
        <div className="space-y-2">
          {ROWS.map((row, rowIndex) => (
            <div key={row} role="row" className="flex items-center gap-2">
              <span className="w-4 text-xs text-muted-foreground">{row}</span>
              {Array.from({ length: COLS }, (_, index) => {
                const col = index + 1
                const id = seatId(row, col)
                const taken = isTaken(rowIndex, col)
                const on = selected.includes(id)
                const focused = cursor.row === rowIndex && (cursor.col || 1) === col
                return (
                  <button
                    key={id}
                    type="button"
                    role="gridcell"
                    aria-label={`${id}${taken ? " 已售" : on ? " 已选" : " 可选"}`}
                    aria-selected={on}
                    aria-disabled={taken}
                    disabled={taken}
                    className={cn(
                      "h-7 flex-1 rounded-md border text-[10px] outline-none",
                      taken && "cursor-not-allowed bg-muted text-muted-foreground",
                      on && "bg-primary text-primary-foreground",
                      focused && "ring-2 ring-primary",
                    )}
                    onClick={() => {
                      setCursor({ row: rowIndex, col })
                      toggle(id, taken)
                    }}
                  >
                    {col}
                  </button>
                )
              })}
            </div>
          ))}
        </div>
      </div>
      <aside className="space-y-3 rounded-xl border p-4">
        <h2 className="text-sm font-medium">场次预览</h2>
        <div className="flex h-16 items-end justify-center gap-1 rounded-md bg-zinc-950 p-2">
          {selected.length === 0 ? <span className="mb-3 text-[10px] text-zinc-400">尚未选座</span> : null}
          {selected.map((id) => (
            <span key={id} className="mb-2 h-3 w-3 rounded-sm bg-primary" title={id} />
          ))}
        </div>
        <p className="text-sm">
          {selected.length} 座 · ¥{total}
        </p>
        <p className="text-xs text-muted-foreground">{selected.join("、") || "用方向键或点击选择空座。"}</p>
      </aside>
    </div>
  )
}

