  className?: string
  duration?: number
  delay?: number
  intensity?: number
}

const ITEMS: readonly ClipRevealItem[] = [
  { id: "work", label: "作品", detail: "从按钮中心撑开" },
  { id: "notes", label: "笔记", detail: "条目依次升起" },
