"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface ClothWindBannerProps {
  className?: string
  texture?: string
  intensity?: number
  speed?: number
  colors?: readonly string[]
}

const DEFAULT_COLORS = ["#7c3aed", "#ea580c"] as const

function useSynced(prop: number | undefined, fallback: number) {
  const [draft, setDraft] = React.useState<{ prop: number | undefined; value: number } | null>(null)
  const value = draft && Object.is(draft.prop, prop) ? draft.value : (prop ?? fallback)
  return [value, (next: number) => setDraft({ prop, value: next })] as const
}

const VERT = `
attribute vec2 uv;
attribute vec3 position;
uniform float u_time;
uniform float u_wind;
uniform float u_speed;
uniform vec2 u_mouse;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
varying vec2 vUv;
varying float vLight;

float heightAt(vec2 p) {
  float wave = sin(p.x * 7.0 + u_time * u_speed * (0.7 + u_wind)) * 0.12;
  wave += sin(p.x * 15.0 - u_time * u_speed * 1.6 + p.y * 5.0) * 0.05;
  wave += sin(p.x * 28.0 + p.y * 19.0 + u_time * u_speed * 2.2) * 0.02;
  float dx = p.x - u_mouse.x;
  float dy = p.y - u_mouse.y;
  float bulge = exp(-(dx * dx + dy * dy) * 14.0) * 0.28;
  float pin = smoothstep(0.0, 0.2, p.x);
  return (wave * u_wind + bulge) * pin;
}

void main() {
  vUv = uv;
  float lift = heightAt(uv);
  float e = 0.02;
  float dx = heightAt(uv + vec2(e, 0.0)) - heightAt(uv - vec2(e, 0.0));
  float dy = heightAt(uv + vec2(0.0, e)) - heightAt(uv - vec2(0.0, e));
  vec3 normal = normalize(vec3(-dx, -dy, 1.0));
  vLight = clamp(dot(normal, normalize(vec3(-0.2, 0.35, 1.0))), 0.25, 1.0);
  vec3 displaced = position + vec3(0.0, 0.0, lift);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(displaced, 1.0);
}
`

const FRAG = `
precision highp float;
uniform sampler2D u_map;
varying vec2 vUv;
varying float vLight;
void main() {
  vec3 tex = texture2D(u_map, vUv).rgb;
  gl_FragColor = vec4(tex * vLight, 1.0);
}
`

function paintBanner(primary: string, secondary: string) {
  const canvas = document.createElement("canvas")
  canvas.width = 512
  canvas.height = 256
  const context = canvas.getContext("2d")
  if (!context) return canvas
  for (let row = 0; row < 8; row += 1) {
    context.fillStyle = row % 2 === 0 ? primary : secondary
    context.fillRect(0, row * 32, 512, 32)
  }
  context.fillStyle = "#fef3c7"
  context.beginPath()
  context.arc(390, 128, 42, 0, Math.PI * 2)
  context.fill()
  return canvas
}

function ClothFallback({ colors }: { colors: readonly string[] }) {
  const primary = colors[0] ?? DEFAULT_COLORS[0]
  const secondary = colors[1] ?? DEFAULT_COLORS[1]
  return (
    <div
      className="absolute inset-x-10 inset-y-16 rounded-md"
      style={{ background: `repeating-linear-gradient(180deg, ${primary} 0 16px, ${secondary} 16px 32px)` }}
    />
  )
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function ClothWindBanner({
  className,
  texture,
  intensity,
  speed = 1,
  colors = DEFAULT_COLORS,
}: ClothWindBannerProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const mouseRef = React.useRef({ x: 0.7, y: 0.5 })
  const windRef = React.useRef(intensity ?? 0.65)
  const speedRef = React.useRef(playbackRate(speed))
  const colorsRef = React.useRef(colors)
  const active = useAnimationActive(hostRef)
  const [wind, setWind] = useSynced(intensity, 0.65)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback
  const label = wind < 0.34 ? "微风" : wind < 0.7 ? "和风" : "劲风"

  React.useEffect(() => {
    windRef.current = wind
    speedRef.current = playbackRate(speed)
    colorsRef.current = colors
  }, [wind, speed, colors])

  React.useEffect(() => {
    if (!showCanvas || !active) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: true, dpr: Math.min(window.devicePixelRatio || 1, 2) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 32 })
      camera.position.set(0, 0, 2.4)
      const scene = new ogl.Transform()
      const geometry = new ogl.Plane(gl, { width: 2.4, height: 0.9, widthSegments: 56, heightSegments: 18 })
      const stripe = texture
        ? [DEFAULT_COLORS[0], DEFAULT_COLORS[1]]
        : [colorsRef.current[0] ?? DEFAULT_COLORS[0], colorsRef.current[1] ?? DEFAULT_COLORS[1]]
      const image = paintBanner(stripe[0] ?? DEFAULT_COLORS[0], stripe[1] ?? DEFAULT_COLORS[1])
      const map = new ogl.Texture(gl, { image, wrapS: gl.CLAMP_TO_EDGE, wrapT: gl.CLAMP_TO_EDGE })
      if (texture) {
        const picture = new Image()
        picture.onload = () => {
          map.image = picture
          map.needsUpdate = true
        }
        picture.src = texture
      }
      const uniforms = {
        u_time: { value: 0 },
        u_wind: { value: windRef.current },
        u_speed: { value: speedRef.current },
        u_mouse: { value: [0.7, 0.5] },
        u_map: { value: map },
      }
      const program = new ogl.Program(gl, { vertex: VERT, fragment: FRAG, uniforms })
      program.cullFace = false
      const mesh = new ogl.Mesh(gl, { geometry, program, frustumCulled: false })
      mesh.setParent(scene)
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect: Math.max(rect.width, 1) / Math.max(rect.height, 1) })
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const started = performance.now()
      let stripeKey = texture ? "" : `${stripe[0]}|${stripe[1]}`
      const tick = () => {
        if (!texture) {
          const primary = colorsRef.current[0] ?? DEFAULT_COLORS[0]
          const secondary = colorsRef.current[1] ?? DEFAULT_COLORS[1]
          const key = `${primary}|${secondary}`
          if (key !== stripeKey) {
            stripeKey = key
            map.image = paintBanner(primary, secondary)
            map.needsUpdate = true
          }
        }
        uniforms.u_time.value = (performance.now() - started) / 1000
        uniforms.u_wind.value = windRef.current
        uniforms.u_speed.value = speedRef.current
        uniforms.u_mouse.value = [mouseRef.current.x, mouseRef.current.y]
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
      }
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [active, showCanvas, texture])

  return (
    <div data-slot="cloth-wind-banner" className={cn("w-full space-y-3", className)}>
      <label className="flex items-center gap-3 text-sm">
        风力
        <input
          type="range"
          min={0}
          max={1}
          step={0.01}
          value={wind}
          aria-valuetext={label}
          className="w-40"
          onChange={(event) => setWind(Number(event.target.value))}
        />
        <span>{label}</span>
      </label>
      <div
        ref={hostRef}
        className="relative h-64 overflow-hidden rounded-xl border bg-slate-950"
        onPointerMove={(event) => {
          const rect = event.currentTarget.getBoundingClientRect()
          mouseRef.current = {
            x: (event.clientX - rect.left) / Math.max(rect.width, 1),
            y: 1 - (event.clientY - rect.top) / Math.max(rect.height, 1),
          }
        }}
      >
        {showCanvas ? <canvas ref={canvasRef} className="absolute inset-0 size-full" /> : <ClothFallback colors={colors} />}
      </div>
    </div>
  )
}

export { ClothWindBanner }

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen, within } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"
import Matter from "matter-js"

import { CoinJar } from "./coin-jar"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()
let createSpy: ReturnType<typeof vi.spyOn>

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
  createSpy = vi.spyOn(Matter.Engine, "create")
})

afterEach(() => {
  cleanup()
  createSpy.mockRestore()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function jar() {
  return screen.getByRole("application", { name: "投币罐" })
}

function stackedCoin() {
  return within(screen.getByRole("list", { name: "罐内" })).getByText("1元")
}

test("默认展示待投入的硬币，不标记减弱动效", () => {
  render(<CoinJar />)
  expect(screen.getByRole("list", { name: "待投入" })).toHaveTextContent("1元")
  expect(screen.getByText("还没有硬币")).toBeInTheDocument()
  expect(screen.getByText("1元")).toHaveStyle({ backgroundColor: "var(--primary)" })
  expect(document.querySelector("[data-slot='coin-jar']")).not.toHaveAttribute("data-reduced")
  expect(document.querySelector("[data-slot='coin-jar']")).toHaveAttribute("data-stacked", "0")
  expect(createSpy).toHaveBeenCalled()
})

test("点击把硬币投入罐中并回调", () => {
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  fireEvent.pointerUp(jar(), { button: 0, clientX: 20, clientY: 40, pointerId: 1, pointerType: "mouse" })
  expect(onDrop).toHaveBeenCalledWith("one")
  expect(jar()).toHaveAttribute("data-stacked", "1")
  expect(screen.getByRole("list", { name: "罐内" })).toHaveTextContent("1元")
  expect(screen.getByRole("list", { name: "待投入" })).not.toHaveTextContent("1元")
  expect(screen.queryByText("还没有硬币")).toBeNull()
})

test("投入后几帧，硬币开始下落", () => {
  render(<CoinJar />)
  fireEvent.pointerUp(jar(), { button: 0, clientX: 12, clientY: 12, pointerId: 1, pointerType: "mouse" })
  const coin = stackedCoin()
  expect(coin.style.transform).toBe("")
  pump(6)
  expect(coin.style.transform).toContain("translate")
})

test("向下键投入一枚硬币", () => {
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  fireEvent.keyDown(jar(), { key: "ArrowDown" })
  expect(onDrop).toHaveBeenCalledWith("one")
  expect(jar()).toHaveAttribute("data-stacked", "1")
})

test("触屏点击同样能投入，不依赖悬停", () => {
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  fireEvent.pointerUp(jar(), { clientX: 16, clientY: 30, pointerId: 3, pointerType: "touch" })
  expect(onDrop).toHaveBeenCalledWith("one")
})

test("减弱动效时硬币直接叠上，不创建引擎也不申请动画帧", () => {
  reduceMotion = true
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  const root = document.querySelector("[data-slot='coin-jar']")
  expect(root).toHaveAttribute("data-reduced", "true")
  expect(root).not.toHaveAttribute("data-physics")
  fireEvent.keyDown(jar(), { key: "Enter" })
  pump(4)
  expect(onDrop).toHaveBeenCalledWith("one")
  expect(stackedCoin().style.transform).toBe("")
  expect(createSpy).not.toHaveBeenCalled()
  expect(queue.size).toBe(0)
})

"use client"

// 原创实现

import { useEffect, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent } from "react"
import Matter from "matter-js"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

const { Bodies, Composite, Engine } = Matter

export interface CoinJarCoin {
  id: string
  label: string
}

export interface CoinJarProps {
  coins?: readonly CoinJarCoin[]
  onDrop?: (id: string) => void
  color?: string
  size?: number
  duration?: number
  className?: string
}

const DEFAULT_COINS: readonly CoinJarCoin[] = [
  { id: "one", label: "1元" },
  { id: "five", label: "5元" },
  { id: "ten", label: "10元" },
  { id: "twenty", label: "20元" },
]

const COIN = 44

interface Anchor {
  x: number
  y: number
}

interface Piece {
  id: string
  body: Matter.Body
  anchor: Anchor
}

interface World {
  engine: Matter.Engine | null
  pieces: Piece[]
  raf: number
}

interface Latest {
  onDrop?: (id: string) => void
  coins: readonly CoinJarCoin[]
  duration: number
  size: number
}

function sceneHeight(size: number) {
  return Math.round(size * 1.15)
}

function mouth(index: number, size: number): Anchor {
  return { x: size / 2 + (index % 2 === 0 ? -10 : 10), y: 28 }
}

function stack(index: number, size: number): Anchor {
  return {
    x: size / 2 + (index % 2 === 0 ? -6 : 6),
    y: sceneHeight(size) - 26 - index * 14,
  }
}

function coinStyle(at: Anchor, accent: string): CSSProperties {
  return {
    backgroundColor: accent,
    color: "var(--primary-foreground)",
    height: COIN,
    left: at.x - COIN / 2,
    top: at.y - COIN / 2,
    width: COIN,
  }
}

function CoinJar({
  coins = DEFAULT_COINS,
  onDrop,
  color,
  size = 220,
  duration = 560,
  className,
}: CoinJarProps) {
  const reduced = usePrefersReducedMotion()
  const accent = color ?? "var(--primary)"
  const height = sceneHeight(size)
  const [dropped, setDropped] = useState<readonly string[]>([])
  const rootRef = useRef<HTMLDivElement>(null)
  const jarRef = useRef<HTMLDivElement>(null)
  const nodes = useRef(new Map<string, HTMLElement>())
  const droppedRef = useRef<string[]>([])
  const world = useRef<World>({ engine: null, pieces: [], raf: 0 })
  const placeRef = useRef<(id: string, index: number) => void>(() => {})
  const latest = useRef<Latest>({ onDrop, coins, duration, size })

  useEffect(() => {
    latest.current = { onDrop, coins, duration, size }
    const jar = jarRef.current
    nodes.current.clear()
    if (!jar) return
    for (const node of jar.querySelectorAll("[data-piece]")) {
      if (!(node instanceof HTMLElement)) continue
      const id = node.dataset.piece
      if (id) nodes.current.set(id, node)
    }
  }, [coins, dropped, duration, onDrop, size])

  useEffect(() => {
    if (reduced) {
      placeRef.current = () => {}
      return
    }
    const engine = Engine.create({ enableSleeping: false, gravity: { scale: 1.4 / duration, y: 1 } })
    const live = world.current
    live.engine = engine
    live.pieces = []
    const thick = 40
    Composite.add(engine.world, [
      Bodies.rectangle(size / 2, height + thick / 2 - 8, size + thick * 2, thick, { isStatic: true }),
      Bodies.rectangle(-thick / 2 + 6, height / 2, thick, height * 2, { isStatic: true }),
      Bodies.rectangle(size + thick / 2 - 6, height / 2, thick, height * 2, { isStatic: true }),
    ])
    const place = (id: string, index: number) => {
      const box = world.current
      if (!box.engine || box.pieces.some((piece) => piece.id === id)) return
      const anchor = mouth(index, latest.current.size)
      const body = Bodies.circle(anchor.x, anchor.y, COIN / 2, {
        density: 0.006,
        friction: 0.92,
        frictionAir: 36 / latest.current.duration,
        restitution: 0.02,
      })
      Composite.add(box.engine.world, body)
      box.pieces.push({ id, body, anchor })
    }
    droppedRef.current.forEach((id, index) => place(id, index))
    placeRef.current = place
    const root = rootRef.current
    if (root) root.dataset.physics = "on"
    let last = 0
    const tick = (now: number) => {
      const box = world.current
      if (!box.engine) return
      const dt = last === 0 ? 16 : Math.min(16, Math.max(1, now - last))
      last = now
      box.engine.gravity.scale = 1.4 / Math.max(160, latest.current.duration)
      const air = 36 / Math.max(160, latest.current.duration)
      for (const piece of box.pieces) piece.body.frictionAir = air
      Engine.update(box.engine, dt)
      for (const piece of box.pieces) {
        const el = nodes.current.get(piece.id)
        if (!el) continue
        const dx = piece.body.position.x - piece.anchor.x
        const dy = piece.body.position.y - piece.anchor.y
        el.style.transform = `translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px) rotate(${piece.body.angle.toFixed(3)}rad)`
      }
      box.raf = requestAnimationFrame(tick)
    }
    live.raf = requestAnimationFrame(tick)
    return () => {
      cancelAnimationFrame(live.raf)
      live.raf = 0
      live.engine = null
      live.pieces = []
      placeRef.current = () => {}
      if (root) delete root.dataset.physics
      Composite.clear(engine.world, false)
      Engine.clear(engine)
    }
  }, [duration, height, reduced, size])

  function dropNext() {
    const next = latest.current.coins.find((coin) => !droppedRef.current.includes(coin.id))
    if (!next) return
    const index = droppedRef.current.length
    droppedRef.current = [...droppedRef.current, next.id]
    setDropped(droppedRef.current)
    latest.current.onDrop?.(next.id)
    placeRef.current(next.id, index)
  }

  function onPointerUp(event: PointerEvent<HTMLDivElement>) {
    if (event.pointerType === "mouse" && event.button !== 0) return
    dropNext()
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "ArrowDown" && event.key !== " " && event.key !== "Enter") return
    event.preventDefault()
    dropNext()
  }

  const waiting = coins.filter((coin) => !dropped.includes(coin.id))
  const piled = dropped.flatMap((id) => {
    const coin = coins.find((item) => item.id === id)
    return coin ? [coin] : []
  })

  return (
    <div
      aria-label="投币罐"
      className={cn(
        "relative flex w-fit flex-col items-center gap-2 outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-current motion-reduce:transition-none",
        className,
      )}
      data-reduced={reduced ? "true" : undefined}
      data-slot="coin-jar"
      data-stacked={dropped.length}
      onKeyDown={onKeyDown}
      onPointerUp={onPointerUp}
      ref={rootRef}
      role="application"
      tabIndex={0}
    >
      <ul aria-label="待投入" className="flex h-12 items-center justify-center gap-2">
        {waiting.map((coin) => (
          <li
            className="grid size-11 place-items-center rounded-full text-[11px] font-medium shadow-sm"
            key={coin.id}
            style={{ backgroundColor: accent, color: "var(--primary-foreground)" }}
          >
            {coin.label}
          </li>
        ))}
      </ul>
      <div className="relative" ref={jarRef} style={{ height, width: size }}>
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 rounded-b-[2rem] rounded-t-lg border-2 border-foreground/20 bg-card/40 shadow-inner"
          style={{ borderColor: accent }}
        />
        <div aria-hidden className="pointer-events-none absolute inset-x-3 top-1.5 h-2 rounded-full bg-foreground/15" />
        <div aria-label="罐内" className="absolute inset-0" role="list">
          {piled.length === 0 ? (
            <p className="text-muted-foreground pointer-events-none absolute inset-x-0 bottom-6 text-center text-xs">还没有硬币</p>
          ) : null}
          {piled.map((coin, index) => {
            const at = reduced ? stack(index, size) : mouth(index, size)
            return (
              <div
                className="pointer-events-none absolute grid place-items-center rounded-full text-[11px] font-medium shadow-md motion-reduce:transition-none"
                data-piece={coin.id}
                key={coin.id}
                role="listitem"
                style={coinStyle(at, accent)}
              >
                {coin.label}
              </div>
            )
          })}
        </div>
      </div>
      <p className="text-muted-foreground text-xs">点击或按向下键投入</p>
    </div>
  )
}

export { CoinJar }

