"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { textStyle } from "@/lib/text-style"
import { cn } from "@/lib/utils"
import { MarqueeAlongSvgPath } from "./marquee-along-svg-path"

export interface CurvedLoopProps {
  text?: string
  className?: string
  /** 沿弧线的速度倍率。不传时起始速度仍是 12。 */
  speed?: number
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

const ARC = "M 24 148 Q 270 8 516 148"

function CurvedLoop({
  text = "CURVED LOOP · ",
  className,
  speed,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: CurvedLoopProps) {
  const reduced = usePrefersReducedMotion()
  const base = speed === undefined || !Number.isFinite(speed) ? 12 : 12 * speed
  const [dragged, setDragged] = React.useState<{ base: number; velocity: number } | null>(null)
  const velocity = dragged !== null && dragged.base === base ? dragged.velocity : base
  const drag = React.useRef<{ x: number } | null>(null)

  return (
    <div data-slot="curved-loop" className={cn("w-full", className)}>
      <div
        className="cursor-ew-resize touch-none"
        onPointerDown={(event) => {
          drag.current = { x: event.clientX }
          event.currentTarget.setPointerCapture(event.pointerId)
        }}
        onPointerMove={(event) => {
          const previous = drag.current
          if (!previous || reduced) return
          const dx = event.clientX - previous.x
          drag.current = { x: event.clientX }
          setDragged((current) => {
            const start = current !== null && current.base === base ? current.velocity : base
            return { base, velocity: Math.max(-28, Math.min(28, start + dx * 0.12)) }
          })
        }}
        onPointerUp={() => {
          drag.current = null
        }}
        onPointerCancel={() => {
          drag.current = null
        }}
      >
        <MarqueeAlongSvgPath
          path={ARC}
          viewBox="0 0 540 180"
          baseVelocity={reduced ? 0 : velocity}
          repeat={8}
          showPath={false}
          className="min-h-48"
        >
          <span
            className="font-display text-4xl whitespace-nowrap sm:text-5xl"
            style={textStyle(undefined, fontSize, fontWeight, letterSpacing, align)}
          >
            {text}
          </span>
        </MarqueeAlongSvgPath>
      </div>
      <p className="text-center text-xs text-muted-foreground">
        {reduced ? "已减弱动效，文字停在弧线上" : `左右拖动改变方向 · ${velocity > 0 ? "→" : "←"} ${Math.abs(velocity).toFixed(0)}`}
      </p>
    </div>
  )
}

export { CurvedLoop }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

export interface CurvedScrollbarProps {
  children?: React.ReactNode
  className?: string
  radius?: number
}

function trackPath(width: number, height: number, radius: number) {
  const inset = 8
  const right = Math.max(inset + radius, width - inset)
  const bottom = Math.max(inset + radius, height - inset)
  const left = inset
  const top = inset
  const corner = Math.min(radius, (right - left) / 2, (bottom - top) / 2)
  return `M ${left + corner} ${top} H ${right - corner} Q ${right} ${top} ${right} ${top + corner} V ${bottom - corner} Q ${right} ${bottom} ${right - corner} ${bottom} H ${left + corner} Q ${left} ${bottom} ${left} ${bottom - corner} V ${top + corner} Q ${left} ${top} ${left + corner} ${top}`
}

function CurvedScrollbar({ children, className, radius = 28 }: CurvedScrollbarProps) {
  const scrollerRef = React.useRef<HTMLDivElement>(null)
  const pathRef = React.useRef<SVGPathElement>(null)
  const [size, setSize] = React.useState({ width: 320, height: 240 })
  const [offset, setOffset] = React.useState(0)
  const [thumb, setThumb] = React.useState(24)
  const [span, setSpan] = React.useState(800)
  const path = trackPath(size.width, size.height, radius)

  const sync = React.useCallback(() => {
    const scroller = scrollerRef.current
    const shape = pathRef.current
    if (!scroller || !shape) return
    const length = shape.getTotalLength()
    const visible = scroller.clientHeight / Math.max(scroller.scrollHeight, 1)
    const thumbLength = Math.max(18, length * visible)
    const travel = Math.max(length - thumbLength, 1)
    const progress = scroller.scrollTop / Math.max(scroller.scrollHeight - scroller.clientHeight, 1)
    setSpan(length)
    setThumb(thumbLength)
    setOffset(progress * travel)
  }, [])

  React.useEffect(() => {
    const scroller = scrollerRef.current
    if (!scroller) return
    const measure = () => {
      const rect = scroller.getBoundingClientRect()
      setSize({ width: rect.width, height: rect.height })
    }
    measure()
    const observer = new ResizeObserver(() => {
      measure()
      sync()
    })
    observer.observe(scroller)
    scroller.addEventListener("scroll", sync, { passive: true })
    return () => {
      observer.disconnect()
      scroller.removeEventListener("scroll", sync)
    }
  }, [sync])

  React.useLayoutEffect(() => {
    sync()
  }, [path, sync])

  return (
    <div data-slot="curved-scrollbar" className={cn("relative", className)}>
      <div ref={scrollerRef} className="h-full overflow-auto pr-6 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {children}
      </div>
      <svg className="pointer-events-none absolute inset-0 size-full" aria-hidden>
        <path ref={pathRef} d={path} fill="none" stroke="currentColor" strokeOpacity="0.25" strokeWidth="3" />
        <path
          d={path}
          fill="none"
          stroke="currentColor"
          strokeWidth="4"
          strokeLinecap="round"
          strokeDasharray={`${thumb} ${Math.max(span - thumb, 0.5)}`}
          strokeDashoffset={-offset}
        />
      </svg>
    </div>
  )
}

export { CurvedScrollbar }

"use client"

// Ported from AI Canvas (MIT, (c) 2026 AI Canvas) — https://github.com/uiNerd16/aicanvas/blob/main/components-workspace/danger-stripes/index.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { useAnimationActive } from "@/hooks/use-animation-active"
import { useCallback, useEffect, useRef } from "react"
import { motion } from "motion/react"

export type DangerStripesTrigger = "mount" | "hover" | "inView"

const STRIPE_TEXT = 'WORK IN PROGRESS \u00A0\u2715\u00A0 DO NOT CLICK OR HOVER \u00A0\u2715\u00A0 DANGER'

const STRIPES = [
  { rotate: -20, top: '40%', bg: '#0a0a0a', fg: '#ffffff' },
  { rotate: 12, top: '47%', bg: '#ffffff', fg: '#0a0a0a' },
  { rotate: -8, top: '54%', bg: '#2a2a2a', fg: '#ffffff' },
]

function RepeatingText({ color, accent }: { color: string; accent: string }) {
  return (
    <div className="flex items-center whitespace-nowrap text-sm font-black tracking-widest uppercase sm:text-base">
      {Array.from({ length: 10 }, (_, i) => (
        <span key={i} style={{ color }}>
          {STRIPE_TEXT.split('\u2715').map((chunk, j, arr) => (
            <span key={j}>
              {chunk}
              {j < arr.length - 1 && (
                <span style={{ color: accent, fontSize: '1.4em' }}>{'\u2715'}</span>
              )}
            </span>
          ))}
          {'\u00A0'}
          <span style={{ color: accent, fontSize: "1.4em" }}>{"\u2715"}</span>
          {'\u00A0 '}
        </span>
      ))}
    </div>
  )
}

function random(min: number, max: number) {
  return Math.random() * (max - min) + min
}

export interface DangerStripesProps {
  /** Stripe field and cross color. Defaults to the primary token. */
  color?: string
  /** How far the stripes shove while disturbed. @default 1 */
  intensity?: number
  /** How quickly the disturbance catches its target. @default 1 */
  speed?: number
  /** When the disturbance runs. @default "hover" */
  trigger?: DangerStripesTrigger
  className?: string
}

export function DangerStripes({
  color = "var(--primary)",
  intensity = 1,
  speed = 1,
  trigger = "hover",
  className = "",
}: DangerStripesProps = {}) {
  const rootRef = useRef<HTMLDivElement>(null)
  const reduced = usePrefersReducedMotion()
  const live = useAnimationActive(rootRef)
  const rafRef = useRef<number>(0)
  const hoveringRef = useRef(false)
  const clickedRef = useRef(false)
  const intensityRef = useRef(0)
  const stripesRef = useRef<(HTMLDivElement | null)[]>([])
  const gainRef = useRef(intensity)
  const speedRef = useRef(speed)
  const liveRef = useRef(live)
  const reducedRef = useRef(reduced)
  useEffect(() => {
    gainRef.current = intensity
    speedRef.current = speed
    liveRef.current = live
    reducedRef.current = reduced
  }, [intensity, speed, live, reduced])

  const frameRef = useRef<() => void>(() => {})
  useEffect(() => {
    frameRef.current = () => {
      if (reducedRef.current || !liveRef.current) {
        intensityRef.current = 0
        stripesRef.current.forEach((el, idx) => {
          const stripe = STRIPES[idx]
          if (el && stripe) el.style.transform = `rotate(${stripe.rotate}deg)`
        })
        rafRef.current = 0
        return
      }
      if (hoveringRef.current || clickedRef.current) {
        const target = (clickedRef.current ? 3 : 1) * gainRef.current
        intensityRef.current += (target - intensityRef.current) * 0.15 * speedRef.current
      } else {
        intensityRef.current *= 0.92
      }

      if (intensityRef.current < 0.005 && !hoveringRef.current && !clickedRef.current) {
        intensityRef.current = 0
        stripesRef.current.forEach((el, idx) => {
          const stripe = STRIPES[idx]
          if (el && stripe) el.style.transform = `rotate(${stripe.rotate}deg)`
        })
        rafRef.current = 0
        return
      }

      const shoveAmount = intensityRef.current

      stripesRef.current.forEach((el, idx) => {
        const stripe = STRIPES[idx]
        if (!el || !stripe) return
        const base = stripe.rotate
        const shove = shoveAmount * speedRef.current
        const tx = random(-18, 18) * shove
        const ty = random(-10, 10) * shove
        const skewX = random(-6, 6) * shove
        const sc = 1 + random(-0.04, 0.04) * shove
        el.style.transform = `rotate(${base}deg) translate(${tx}px, ${ty}px) skewX(${skewX}deg) scale(${sc})`
      })

      rafRef.current = requestAnimationFrame(() => frameRef.current())
    }
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current)
    }
  }, [])

  const startLoop = useCallback(() => {
    if (rafRef.current) return
    rafRef.current = requestAnimationFrame(() => frameRef.current())
  }, [])

  const triggerHover = useCallback(() => {
    hoveringRef.current = true
    startLoop()
  }, [startLoop])

  const triggerClick = useCallback(() => {
    clickedRef.current = true
    startLoop()
    setTimeout(() => {
      clickedRef.current = false
    }, 500)
  }, [startLoop])

  const triggerLeave = useCallback(() => {
    hoveringRef.current = false
  }, [])

  useEffect(() => {
    if (reduced) return
    const armed = trigger === "mount" || (trigger === "inView" && live)
    hoveringRef.current = armed
    if (armed && live) startLoop()
    if (!armed && trigger !== "hover") hoveringRef.current = false
  }, [trigger, live, reduced, startLoop])

  return (
    <div
      ref={rootRef}
      data-reduced={reduced ? "true" : "false"}
      data-motion={live && !reduced ? "on" : "off"}
      className={`motion-reduce:transition-none flex min-h-80 w-full items-stretch justify-center ${className}`}
      style={{ background: color }}
    >
      <div className="relative w-full overflow-hidden select-none">
        {STRIPES.map((stripe, i) => (
          <motion.div
            key={i}
            ref={(el) => { stripesRef.current[i] = el }}
            className="absolute left-[-40%] flex h-[60px] w-[180%] items-center overflow-hidden sm:h-[72px]"
            style={{
              top: stripe.top,
              background: stripe.bg,
              boxShadow: '0 4px 24px rgba(0,0,0,0.4), 0 1px 8px rgba(0,0,0,0.3)',
              willChange: 'transform',
              cursor: 'pointer',
            }}
            initial={{ x: i % 2 === 0 ? -300 : 300, opacity: 0, rotate: stripe.rotate }}
            animate={{ x: 0, opacity: 1, rotate: stripe.rotate }}
            transition={{
              duration: 0.6,
              delay: i * 0.12,
              ease: 'easeOut',
            }}
            onPointerEnter={(event) => {
              if (trigger !== "hover") return
              if (event.pointerType === "touch") return
              triggerHover()
            }}
            onPointerLeave={() => {
              if (trigger !== "hover") return
              triggerLeave()
            }}
            onPointerDown={(event) => {
              if (event.pointerType === "mouse" && trigger === "hover") triggerClick()
              if (event.pointerType !== "mouse") {
                triggerHover()
                triggerClick()
              }
            }}
            onPointerUp={(event) => {
              if (event.pointerType === "mouse") return
              window.setTimeout(triggerLeave, 600)
            }}
          >
            <RepeatingText color={stripe.fg} accent={color} />
          </motion.div>
        ))}
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface DataTunnelProps {
  className?: string
  count?: number
  speed?: number
  colors?: readonly string[]
  intensity?: number
}

const DEFAULT_COLORS = ["#0d3347", "#a6f2ff"] as const

type Rgb = [number, number, number]

function hexToRgb(hex: string, fallback: Rgb): Rgb {
  const text = hex.trim().replace(/^#/, "")
  const digits = text.length === 3 ? [...text].map((char) => `${char}${char}`).join("") : text
  if (!/^[0-9a-fA-F]{6}$/.test(digits)) return fallback
  const value = Number.parseInt(digits, 16)
  return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
}

const VERT = `
attribute vec3 position;
attribute vec2 uv;
attribute vec3 aCenter;
attribute float aCell;
uniform float u_depth;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
varying vec2 vUv;
void main() {
  float z = mod(aCenter.z - u_depth, 8.0) - 4.0;
  vec3 p = vec3(aCenter.x, aCenter.y, 0.0) + position * vec3(0.09, 0.045, 1.0);
  p.z += z;
  vUv = vec2((uv.x + mod(aCell, 16.0)) / 16.0, uv.y);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
}
`

const FRAG = `
precision highp float;
uniform sampler2D u_atlas;
uniform vec3 u_bg;
uniform vec3 u_glyph;
uniform float u_intensity;
varying vec2 vUv;
void main() {
  float glyph = texture2D(u_atlas, vUv).r;
  vec3 color = mix(u_bg, u_glyph * u_intensity, glyph);
  gl_FragColor = vec4(color, 0.35 + glyph * 0.65);
}
`

const CHARS = "0123456789ABCDEF"

function paintAtlas() {
  const canvas = document.createElement("canvas")
  canvas.width = 512
  canvas.height = 32
  const context = canvas.getContext("2d")
  if (!context) return canvas
  context.fillStyle = "#042f2e"
  context.fillRect(0, 0, 512, 32)
  context.fillStyle = "#ecfeff"
  context.font = "22px monospace"
  context.textAlign = "center"
  context.textBaseline = "middle"
  for (let index = 0; index < CHARS.length; index += 1) {
    context.fillText(CHARS[index] ?? "", index * 32 + 16, 17)
  }
  return canvas
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function DataTunnel({
  className,
  count: ringCount = 10,
  speed = 1,
  colors = DEFAULT_COLORS,
  intensity = 1,
}: DataTunnelProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const boost = React.useRef(0)
  const speedRef = React.useRef(playbackRate(speed))
  const colorsRef = React.useRef(colors)
  const intensityRef = React.useRef(intensity)
  const active = useAnimationActive(hostRef)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback

  React.useEffect(() => {
    speedRef.current = playbackRate(speed)
    colorsRef.current = colors
    intensityRef.current = intensity
  }, [speed, colors, intensity])

  React.useEffect(() => {
    if (!showCanvas || !active) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: false, dpr: Math.min(window.devicePixelRatio || 1, 2) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 42, near: 0.1, far: 20 })
      camera.position.z = 0.2
      const rings = Math.max(1, Math.round(ringCount))
      const segments = 14
      const count = rings * segments
      const centers = new Float32Array(count * 3)
      const cells = new Float32Array(count)
      for (let ring = 0; ring < rings; ring += 1) {
        for (let segment = 0; segment < segments; segment += 1) {
          const index = ring * segments + segment
          const angle = (segment / segments) * Math.PI * 2
          const radius = 0.72 + (ring % 3) * 0.08
          centers[index * 3] = Math.cos(angle) * radius
          centers[index * 3 + 1] = Math.sin(angle) * radius
          centers[index * 3 + 2] = ring * 0.8
          cells[index] = (ring + segment) % CHARS.length
        }
      }
      const geometry = new ogl.Geometry(gl, {
        position: { size: 3, data: new Float32Array([-1, -1, 0, 1, -1, 0, -1, 1, 0, 1, 1, 0]) },
        uv: { size: 2, data: new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]) },
        index: { data: new Uint16Array([0, 1, 2, 2, 1, 3]) },
        aCenter: { size: 3, data: centers, instanced: 1 },
        aCell: { size: 1, data: cells, instanced: 1 },
      })
      const atlas = new ogl.Texture(gl, { image: paintAtlas(), minFilter: gl.LINEAR, magFilter: gl.LINEAR })
      const uniforms = {
        u_depth: { value: 0 },
        u_atlas: { value: atlas },
        u_bg: { value: hexToRgb(colorsRef.current[0] ?? DEFAULT_COLORS[0], [0.05, 0.2, 0.28]) },
        u_glyph: { value: hexToRgb(colorsRef.current[1] ?? DEFAULT_COLORS[1], [0.65, 0.95, 1]) },
        u_intensity: { value: intensityRef.current },
      }
      const program = new ogl.Program(gl, {
        vertex: VERT,
        fragment: FRAG,
        uniforms,
        transparent: true,
        depthWrite: false,
      })
      const scene = new ogl.Transform()
      const mesh = new ogl.Mesh(gl, { geometry, program, frustumCulled: false })
      mesh.setParent(scene)
      let depth = 0
      let speed = 0.35
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect: Math.max(rect.width, 1) / Math.max(rect.height, 1), fov: camera.fov })
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const tick = () => {
        speed += boost.current
        speed = Math.max(0.18, Math.min(2.4, speed * 0.96))
        boost.current *= 0.9
        depth += speed * 0.04 * speedRef.current
        uniforms.u_bg.value = hexToRgb(colorsRef.current[0] ?? DEFAULT_COLORS[0], [0.05, 0.2, 0.28])
        uniforms.u_glyph.value = hexToRgb(colorsRef.current[1] ?? DEFAULT_COLORS[1], [0.65, 0.95, 1])
        uniforms.u_intensity.value = intensityRef.current
        uniforms.u_depth.value = depth
        const fov = 38 + speed * 16
        camera.fov = fov
        camera.perspective({ fov, aspect: gl.canvas.width / Math.max(gl.canvas.height, 1) })
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
      }
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [active, ringCount, showCanvas])

  return (
    <div data-slot="data-tunnel" className={cn("w-full space-y-2", className)}>
      <p className="text-xs text-muted-foreground">滚动或按住加速。视野会随速度张开。减弱动效时保持静止。</p>
      <div
        ref={hostRef}
        role="img"
        aria-label="数据隧道"
        className="relative h-72 overflow-hidden rounded-xl border bg-slate-950"
        onWheel={(event) => {
          if (reduced) return
          event.preventDefault()
          boost.current += Math.min(0.4, Math.abs(event.deltaY) * 0.0015)
        }}
        onPointerDown={() => {
          boost.current += 0.35
        }}
      >
        {showCanvas ? (
          <canvas ref={canvasRef} className="absolute inset-0 size-full" />
        ) : (
          <div
            className="absolute inset-0"
            style={{
              background:
                "radial-gradient(circle at 50% 50%, #e0f2fe 0 3%, transparent 4%), repeating-radial-gradient(circle at 50% 50%, transparent 0 16px, rgba(34,211,238,0.4) 16px 18px)",
            }}
          />
        )}
      </div>
    </div>
  )
}

export { DataTunnel }
